    /// Intensity for a rendered pixel, or nil when the colour is not on the ramp
    /// — an anti-aliased edge, or a pixel the service composited. Unknown stays
    /// unknown rather than guessing a value that would set an opacity.
    public static func intensity(r: UInt8, g: UInt8, b: UInt8) -> Float? {
        let key = (UInt32(r) << 16) | (UInt32(g) << 8) | UInt32(b)
        var lo = 0, hi = keys.count - 1
        while lo <= hi {
            let mid = (lo + hi) / 2
            if keys[mid] == key { return intensities[mid] }
            if keys[mid] < key { lo = mid + 1 } else { hi = mid - 1 }
        }
        return nil
    }

    public static let stepCount = 238
}
